//! The five Apps SDK UI icons these components use by default (Alert's
//! indicator and CopyButton's two states), so the components render without
//! the icon module. Paths from `src/components/Icon/svg/*.tsx` (MIT).
//! Any `impl Render` (such as the generated `Icon` enum) can replace them.

use maud::{Markup, PreEscaped};

const OPEN: &str = r#"<svg width="1em" height="1em" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" focusable="false">"#;

fn svg(paths: &str) -> Markup {
    PreEscaped(format!("{OPEN}{paths}</svg>"))
}

